# =====================================================================
# NaijaDrops Fix Script #3 - generated by Claude
# Fixes in this batch:
#   1. Negotiation is now truly locked shut once both sides actually agree
#      on a price - whether that agreement happened by the vendor accepting
#      a rider's bid pre-match, or either side accepting a proposed offer
#      in chat post-match. All "propose a price" / "negotiate with rider
#      first" entry points disappear the instant that happens (new
#      orders.price_locked column + DB-enforced, not just hidden in the UI).
#      Matching a rider at the plain asking price (no negotiation involved)
#      does NOT lock it - one round of real negotiation is still available
#      in that case, since nothing was actually agreed yet.
#   2. The chat header now shows whatever price is actually on the table
#      right now - a newer pending offer overrides the stale agreed price
#      in the display the instant it's sent, until it's accepted, declined,
#      or superseded by a further offer.
#   3. A rider now gets a clear, explicit notice when a vendor declines
#      their bid, instead of the offer just silently disappearing.
#   4. The legacy "Find a Driver" page (Quick Match / Negotiate Price
#      toggle - the one in your screenshots) no longer runs its own
#      separate matching + negotiation system. It now only creates the
#      order, then hands off immediately to /tracking/[orderId], which is
#      where all matching, bidding, negotiating, and paying already lives.
#
# Run this from the ROOT of your NaijaDrops project folder
# (the folder that contains "src", "package.json", etc.)
#
# Usage:
#   powershell -ExecutionPolicy Bypass -File .\Fix-NaijaDrops-Price-Lock-Handoff.ps1
# =====================================================================

$ErrorActionPreference = "Stop"
$ts = Get-Date -Format "yyyyMMdd_HHmmss"
$root = Get-Location

function Write-FileNoBom {
    param([string]$RelativePath, [string]$Base64Content)

    $fullPath = Join-Path $root $RelativePath
    $dir = Split-Path $fullPath -Parent

    if (-not (Test-Path -LiteralPath $dir)) {
        New-Item -ItemType Directory -Path $dir -Force | Out-Null
        Write-Host "  Created directory: $dir" -ForegroundColor DarkGray
    }

    if (Test-Path -LiteralPath $fullPath) {
        $backupPath = "$fullPath.bak_$ts"
        Copy-Item -LiteralPath $fullPath -Destination $backupPath -Force
        Write-Host "  Backed up existing file to: $(Split-Path $backupPath -Leaf)" -ForegroundColor DarkGray
    }

    $bytes = [System.Convert]::FromBase64String($Base64Content)
    $text = [System.Text.Encoding]::UTF8.GetString($bytes)
    $noBomUtf8 = New-Object System.Text.UTF8Encoding($false)
    [System.IO.File]::WriteAllText($fullPath, $text, $noBomUtf8)

    Write-Host "  Wrote: $RelativePath" -ForegroundColor Green
}

Write-Host ""
Write-Host "NaijaDrops fix script #3 starting..." -ForegroundColor Cyan
Write-Host "Project root: $root" -ForegroundColor Cyan
Write-Host ""

Write-Host "Processing: src/components/OrderChat.jsx" -ForegroundColor White
